<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';import {analyticsChoice,saveAnalyticsChoice,recordPublicView} from '@/publicAnalytics';
const enabled=ref(false),note=ref('不参与分析，不影响使用。');let controller=new AbortController(),timer:ReturnType<typeof setTimeout>|null=null;
function storage(){try{return localStorage;}catch{return null;}}
async function record(){controller.abort();controller=new AbortController();const current=controller,signal=current.signal;if(timer)clearTimeout(timer);const ownTimer=setTimeout(()=>current.abort(),5000);timer=ownTimer;try{const result=await recordPublicView(storage(),signal);if(!signal.aborted)note.value=result==='disabled'?'已记住选择；服务器暂未启用分析。':result==='recorded'?'已记录本次匿名估算；可随时退出。':'分析暂不可用，不影响使用，不会自动重试。';}catch{if(enabled.value&&!signal.aborted)note.value='分析未完成，不影响使用，不会自动重试。';}finally{clearTimeout(ownTimer);if(timer===ownTimer)timer=null;}}
function change(){saveAnalyticsChoice(enabled.value,storage());if(enabled.value)void record();else{controller.abort();note.value='已退出分析，并移除本机短期访客标识。';}}
onMounted(()=>{enabled.value=analyticsChoice(storage());if(enabled.value)void record();});onUnmounted(()=>{controller.abort();if(timer)clearTimeout(timer);});
</script>
<template><section class="analysis-choice" aria-label="官网可选访客分析"><details><summary>隐私与可选访客分析</summary><p>仅在你主动参与后，记录介绍页的浏览量和按日去重的访客估算。每天更换随机标识，不与账号、邮箱关联，不跨站、不采集指纹。无法保存标识时只计参与浏览，不估算访客。</p><p>服务端短期去重记录48小时到期、日汇总保留90天；跨日只能展示“日去重访客合计”，不是精确人数。服务器运行安全仅保留分类、状态和耗时聚合，不向面板提供原始URL、IP或UA。既有受限服务器日志单独管理。</p><label><input v-model="enabled" type="checkbox" @change="change"/>参与官网匿名访客估算（可选，默认关闭）</label><p role="status">{{note}}</p></details></section></template>
<style scoped>.analysis-choice{max-width:1320px;margin:24px auto;padding:24px;border:1px solid #d7dce4;background:#fff;color:#20242e;font-family:"Helvetica Neue",Arial,sans-serif}.analysis-choice summary{font-weight:700;cursor:pointer}.analysis-choice p{font-size:13px;line-height:1.9}.analysis-choice label{display:flex;gap:12px;align-items:center;font-size:14px}.analysis-choice input{width:20px;height:20px;flex:0 0 20px;accent-color:#002fa7}@media(max-width:700px){.analysis-choice{margin:20px;padding:16px}}</style>
